class Solution {
public:
    long long numberOfWays(string s) {
        long long c0 = 0, c01 = 0, c010 = 0;
        long long c1 = 0, c10 = 0, c101 = 0;
        for (char ch : s) {
            if (ch == '0') {
                c010 += c01;
                c0 += 1;
                c10 += c1;
            } else {
                c101 += c10;
                c1 += 1;
                c01 += c0;
            }
        }
        return c010 + c101;
    }
};
